ALTER TABLE runs ADD COLUMN tool_limit integer NOT NULL DEFAULT 4 CHECK(tool_limit BETWEEN 0 AND 32);
CREATE TABLE schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,room_id uuid REFERENCES rooms(id) DEFERRABLE,name text NOT NULL,prompt text NOT NULL,rule text NOT NULL,timezone text NOT NULL,at text NOT NULL,interval_seconds integer NOT NULL,enabled boolean NOT NULL DEFAULT false,catch_up text NOT NULL DEFAULT 'latest',executor text NOT NULL DEFAULT 'cloud',device_id uuid REFERENCES devices(id),host_id uuid,tool_limit integer NOT NULL DEFAULT 5,next_at timestamptz NOT NULL,revision integer NOT NULL DEFAULT 1,epoch integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE schedule_occurrences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),schedule_id uuid NOT NULL REFERENCES schedules(id) DEFERRABLE,slot text NOT NULL,scheduled_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'pending',run_id uuid REFERENCES runs(id) DEFERRABLE,host_job_id uuid,executor text NOT NULL,epoch integer NOT NULL,notification_state text NOT NULL DEFAULT 'not_scheduled',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(schedule_id,slot));
CREATE TABLE event_triggers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,room_id uuid NOT NULL REFERENCES rooms(id) DEFERRABLE,name text NOT NULL,mode text NOT NULL,service text NOT NULL,node_id text NOT NULL,secret jsonb NOT NULL,enabled boolean NOT NULL DEFAULT false,state text NOT NULL DEFAULT 'registered',external_id text,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE received_events(trigger_id uuid NOT NULL REFERENCES event_triggers(id) DEFERRABLE,event_id text NOT NULL,payload_hash text NOT NULL,run_id uuid REFERENCES runs(id) DEFERRABLE,message_id uuid REFERENCES messages(id) DEFERRABLE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(trigger_id,event_id));
ALTER TABLE messages ADD COLUMN external_origin jsonb;
ALTER TABLE runs ADD COLUMN schedule_id uuid REFERENCES schedules(id) DEFERRABLE;
ALTER TABLE runs ADD COLUMN schedule_revision integer;
ALTER TABLE runs ADD COLUMN schedule_epoch integer;
